'use strict';

class MdsSelectorUtility {
  static toggleSelectorChecked(selector, selected, emit = true, multiselect, changeEmitter) {
    selector.checked = selected;
    let value = selector.checked;
    if (!multiselect) {
      value = selector.checked ? selector['value'] : '';
    }
    if (emit) {
      changeEmitter.emit(value);
    }
    return value;
  }
  static getRadioCheckedValue(value, externalFormValue) {
    // We need to check against a possible external form value in case the external form value property
    // was set before the value property was fully initialized
    return ((!!value || value === false || value === 0) && value === externalFormValue);
  }
}

exports.MdsSelectorUtility = MdsSelectorUtility;
